  self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_document_bindings WHERE order_id=?',params=[oid])[0]['n'],0)
  r=self.own('links',order_id=oid,document_ids=[],details=True,confirm=True,send_email=False);guest,x=self.exchange(r.json()['url'].split('#token=')[1]);self.consent(guest,x);data={k:'' for k in guest.get(self.base+'/prospect-api.php?r=details').json()['labels']};data.update(type='person',name='ТЕСТОВЫЙ Новый Заказчик',email=self.invite_email,purpose='personal',represented='no');did=self.must(guest.post(self.base+'/prospect-api.php?r=details',json={'prior_id':0,'data':data,'submit':True}))['id'];self.must(self.ctp('review',id=did,version=1,approve=True,reason='SYNTHETIC fresh identity check',authority_review='SYNTHETIC acts personally'))
  return oid,values,history
