  return dict(order_id=oid,version=int(records['flow']['version']),order_version=int(records['context']['order_version']),quotation_id=int(quote['id']),quotation_hash=quote['checksum'],values=v,template_ids=[int(t['id']) for t in self.templates[:2]],confirm=True,accept_estimates=True,reason='SYNTHETIC owner checked exact price and all terms')
