   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);context=browser.new_context(viewport={'width':375,'height':812});context.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in self.owner.cookies]);page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(self.base+'/order-workflow.php?order='+str(oid)+'&stage=acceptance');button=page.get_by_role('button',name='Подготовить акт принятого результата',exact=True);button.wait_for();form=page.locator('form').filter(has=button)
   for name,value in values.items():form.locator('[name="'+name+'"]').fill(value)
   form.get_by_role('checkbox',name='Я проверил фактический состав акта',exact=False).check();button.click();page.wait_for_url('**stage=act**');self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(errors,[]);binding=int(page.url.split('#document/')[1]);browser.close();return self.lg('documents/'+str(binding)).json()['record']
